class LockingTree {
  private final int[] parent;
  private final int[] owner; // 0 when unlocked
  private final List<Integer>[] children;

  public LockingTree(int[] parent) {
    this.parent = parent;
    owner = new int[parent.length];
    children = new List[parent.length];
    for (int i = 0; i < parent.length; i++) children[i] = new ArrayList<>();
    for (int i = 1; i < parent.length; i++) children[parent[i]].add(i);
  }

  public boolean lock(int num, int user) {
    if (owner[num] != 0) return false;
    owner[num] = user;
    return true;
  }

  public boolean unlock(int num, int user) {
    if (owner[num] != user) return false;
    owner[num] = 0;
    return true;
  }

  public boolean upgrade(int num, int user) {
    if (owner[num] != 0) return false;
    for (int p = parent[num]; p != -1; p = parent[p]) if (owner[p] != 0) return false;
    if (!hasLockedDescendant(num)) return false;
    unlockDescendants(num);
    owner[num] = user;
    return true;
  }

  private boolean hasLockedDescendant(int node) {
    Deque<Integer> stack = new ArrayDeque<>(children[node]);
    while (!stack.isEmpty()) {
      int u = stack.pop();
      if (owner[u] != 0) return true;
      stack.addAll(children[u]);
    }
    return false;
  }

  private void unlockDescendants(int node) {
    Deque<Integer> stack = new ArrayDeque<>(children[node]);
    while (!stack.isEmpty()) {
      int u = stack.pop();
      owner[u] = 0;
      stack.addAll(children[u]);
    }
  }
}

